style.css:
@-moz-document domain("pinterest.com") {
/* 1. Main Background & Navigation */
    body, 
    #HeaderContent, 
    .FullPageModal__scroller,
    [data-test-id="full-grid-container"] {
        background-color: #FFF9F0 !important;
    }

    /* 2. Header and Search Bar */
    [data-test-id="header-background"],
    [data-test-id="search-box-container"] {
        background-color: #FFF9F0 !important;
        border-bottom: 2px solid #EAD7BB !important;
    }

    [data-test-id="search-box-input"] {
        background-color: #F5E6D3 !important;
        color: #4E342E !important;
    }

    /* 3. The "Strawberry" Accents (Buttons & Interactions) */
    /* Primary buttons (Save, Follow, etc.) */
    [data-test-id="pdp-buy-it-button"],
    [data-test-id="board-section-follow-button"],
    .red.active,
    div[style*="background-color: rgb(230, 0, 35)"] {
        background-color: #FF85A1 !important;
    }

    /* 4. The "Chocolate" Text and Icons */
    h1, h2, h3, div, span, p {
        color: #4E342E !important;
    }
    
    /* Navigation Icons */
    svg {
        fill: #4E342E !important;
    }

    /* 5. Pin Cards & Borders */
    [data-test-id="pin-visual-wrapper"] {
        border-radius: 24px !important;
        overflow: hidden !important;
        box-shadow: 0 4px 12px rgba(78, 52, 46, 0.1) !important;
    }

    /* 6. Hover States */
    div[role="button"]:hover, 
    a:hover {
        background-color: #FCE4EC !important; /* Soft strawberry milk hover */
        transition: background-color 0.3s ease;
    }

    /* 7. Scrollbar Customization */
    ::-webkit-scrollbar {
        width: 10px;
    }
    ::-webkit-scrollbar-track {
        background: #FFF9F0;
    }
    ::-webkit-scrollbar-thumb {
        background: #D7CCC8; 
        border-radius: 10px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #FF85A1;
    }
}
